const matchBlock = ({ heading, sub, score, matched, missing }) => `
<div style="border:1px solid #eadff0;border-radius:10px;padding:16px;margin:0 0 12px">
  <div style="font-weight:bold;font-size:16px">${esc(heading)}</div>
